  "PROP-57888860-inv-012": {
    "property_id": "PROP-57888860-inv-012",
    "text": "Inverse FFT must apply normalization factor 1/N and reverse roots order (except first element).",
    "type": "invariant",
    "assertion": "forall fft_field(vals, roots, inv=True): result == [x * (1/len(vals)) for x in _fft_field(vals, reverse(roots[1:]))]",
    "severity": "HIGH",
    "covers": "SG-004",
    "reachability": {
      "classification": "external-reachable",
      "entry_points": [
        "P2P"
      ],
