   131→    /* Ensure the length is valid */
   132→    if (n > FIELD_ELEMENTS_PER_EXT_BLOB || !is_power_of_two(n)) {
   133→        return C_KZG_BADARGS;
   134→    }
   135→
   136→    size_t stride = FIELD_ELEMENTS_PER_EXT_BLOB / n;
   137→    fr_fft_fast(out, in, 1, s->reverse_roots_of_unity, stride, n);
   138→
   139→    fr_t inv_n;
   140→    fr_from_uint64(&inv_n, n);
   141→    blst_fr_eucl_inverse(&inv_n, &inv_n);
   142→    for (size_t i = 0; i < n; i++) {
   143→        blst_fr_mul(&out[i], &out[i], &inv_n);
   144→    }
   145→    return C_KZG_OK;
   146→}
