   218→ * @param[in]   in  The input data, length `n`
   219→ * @param[in]   n   Length of the arrays
   220→ * @param[in]   s   The trusted setup
   221→ *
   222→ * @remark Will do nothing if given a zero length array.
   223→ * @remark The array lengths must be a power of two.
   224→ * @remark Use g1_fft() for forward transformation.
   225→ */
   226→C_KZG_RET g1_ifft(g1_t *out, const g1_t *in, size_t n, const KZGSettings *s) {
   227→    /* Handle zero length input */
   228→    if (n == 0) return C_KZG_OK;
   229→
   230→    /* Ensure the length is valid */
