   232→        return C_KZG_BADARGS;
   233→    }
   234→
   235→    size_t stride = FIELD_ELEMENTS_PER_EXT_BLOB / n;
   236→    g1_fft_fast(out, in, 1, s->reverse_roots_of_unity, stride, n);
   237→
   238→    fr_t inv_n;
   239→    fr_from_uint64(&inv_n, n);
