   252→/**
   253→ * Do an FFT over a coset of the roots of unity.
   254→ *
   255→ * @param[out]  out The results, length `n`
   256→ * @param[in]   in  The input data, length `n`
   257→ * @param[in]   n   Length of the arrays
   258→ * @param[in]   s   The trusted setup
   259→ *
   260→ * @remark Will do nothing if given a zero length array.
   261→ * @remark The coset shift factor is RECOVERY_SHIFT_FACTOR.
   262→ */
   263→C_KZG_RET coset_fft(fr_t *out, const fr_t *in, size_t n, const KZGSettings *s) {
   264→    /* Handle zero length input */
   265→    if (n == 0) return C_KZG_OK;
   266→
   267→    /* Create some room to shift the polynomial */
   268→    fr_t *in_shifted = NULL;
   269→    C_KZG_RET ret = new_fr_array(&in_shifted, n);
   270→    if (ret != C_KZG_OK) goto out;
   271→
   272→    /* Shift the poly */
   273→    memcpy(in_shifted, in, n * sizeof(fr_t));
   274→    shift_poly(in_shifted, n, &RECOVERY_SHIFT_FACTOR);
   275→
   276→    ret = fr_fft(out, in_shifted, n, s);
   277→    if (ret != C_KZG_OK) goto out;
